    let mut score = post_residual as f64;

    // Penalize creating a new bin if it won't be used
    if open_bins_count == 0 && post_residual < 10 {
        score += 5.0;
    }

    // Reward using bins with higher mean residual
    score -= (mean_residual / 10.0).powi(2);

    // Penalize bins that cannot fit the next item
    if fitting_bins_count == 0 && next_item_size > bin_residual {
        score += 3.0;
    }

    // Reward using bins with less open space
    score -= (post_residual / bin_capacity as f64).powi(2);

    // Penalize creating too many bins
    score += (open_bins_count as f64 - mean_residual) * 2.0;

    score
}

