    score -= (post_residual / bin_capacity as f64).powi(2);

    // Penalize creating too many bins
    score += (open_bins_count as f64 - mean_residual) * 1.5;

    // Lookahead penalty for future items not fitting in the current bin
    if next_item_size > bin_residual {
        score += (total_items - step_index) as f64 * 2.0;
    }

    // Reward if we can fit more items in the current bin
    if post_residual >= item_size {
        score -= 0.2 * fitting_bins_count as f64;
    }

    // Additional penalty for bins with a high number of small items
    if bin_capacity - bin_residual < 10 && fitting_bins_count > 5 {
        score += 3.0;
    }

    // Reward for using bins that are more likely to fit the next item
    if fitting_bins_count > 0 {
        score -= (next_item_size as f64 / bin_residual as f64).powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
