pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize small gaps that cannot fit the next item
    if post_residual < next_item_size {
        score -= (next_item_size - post_residual) as f64 * 100.0;
    }

    // Favor bins with smaller mean residual to spread items more evenly
    score -= mean_residual / bin_capacity;

    // Penalize creating new bins when there are fitting open bins
    if fitting_bins_count > 0 {
        score += (fitting_bins_count as f64 - 1.0) * 50.0;
    }

    // Penalize high number of open bins to encourage consolidating items into fewer bins
    score -= open_bins_count as f64 * 20.0;

    // Reward higher bin capacity utilization
    if bin_residual < bin_capacity {
        score += (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let stream_progress = step_index as f64 / total_items as f64;
    let score = -post_residual as f64 * stream_progress.powi(2);
    score
}
